-- Nach 0-gemeinsam.sql ausführen. Mehrfach ausführbar, gespielte Runden bleiben erhalten.

begin;

delete from public.massnahmen where thema_id = 34;
delete from public.abdeckung where thema_id = 34;
delete from public.pruef_einheiten where thema_id = 34;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9631, 34, 'Kontrollquittung mit Grund und Rechtsgrundlage bei Polizeikontrollen (Land)', 'Ein schriftlicher Kontrollgrund macht Kontrollen nachprüfbar; in Fuenlabrada (Spanien) sanken Kontrollzahl und Ungleichbehandlung, dort aber zusammen mit Schulung und Datenauswertung. Ohne Auswertung bleibt die Wirkung unsicher.', 'gemischt', 'https://liberties.eu/en/news/stop-forms-ethnic-profiling-spain/16436', 'land', null, true, 'blind'),
  (9632, 34, 'Anlasslose Kontrollen begrenzen, kriminalitätsbelastete Orte und Waffenverbotszonen abschaffen (Land)', 'Weniger anlasslose Kontrollen senken die Zahl belastender Kontakte, die in Studien mit Stress und Angst junger Menschen zusammenhängen. Kontrollen mit Verdacht bleiben, daher ist nur ein Teil der Kontakte betroffen.', 'belegt', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'land', null, true, 'blind'),
  (9633, 34, 'Kriterien und parlamentarische Kontrolle für kriminalitätsbelastete Orte (Land)', 'Klare, öffentliche Kriterien und Kontrolle durch das Parlament können die Ausweisung solcher Orte begrenzen; die Befugnis zu anlasslosen Kontrollen bleibt aber bestehen. Zur Wirkung gibt es kaum Untersuchungen.', 'offen', null, 'land', null, true, 'blind'),
  (9634, 34, 'Mehr anlasslose Kontrollen und höherer Kontrolldruck im öffentlichen Raum (Land)', 'Mehr Kontrollen erhöhen die Zahl der Kontakte, die in Studien mit psychischer Belastung junger Menschen zusammenhängen; für respektvolle, verhältnismäßige Kontakte hilft das nicht. Ziel ist Sicherheit, nicht der Umgang.', 'belegt', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'land', null, true, 'blind'),
  (9635, 34, 'Unabhängige Polizeibeauftragte oder Beschwerdestelle schaffen bzw. mit Befugnissen stärken (Land)', 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'gemischt', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'land', null, true, 'blind'),
  (9636, 34, 'Unabhängige Ermittlungsstelle für Vorwürfe von Polizeigewalt (Land)', 'Setzt an der Abhängigkeit der Strafverfahren von polizeilichen Ermittlungen an; ähnliche Stellen gibt es in anderen Staaten. Belastbare Wirkungsstudien fehlen, Aufbau und Personal brauchen Zeit.', 'gemischt', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'land', null, true, 'blind'),
  (9637, 34, 'Individuelle Kennzeichnungspflicht für Polizeikräfte (Land)', 'Erkennbare Beamte sind Voraussetzung, um Vorwürfe einer Person zuzuordnen; der EGMR rügte 2017 unter anderem fehlende Identifizierbarkeit. Wirkungsstudien gibt es kaum, viele Länder haben die Pflicht bereits.', 'offen', null, 'land', null, true, 'blind'),
  (9638, 34, 'Bodycam-Pflicht bei Einsätzen oder Zwang, mit Löschschutz bzw. Recht auf Einschalten (Land)', 'Aufnahmen sichern Beweise für die Klärung von Vorwürfen; laut Campbell-Review sinken Beschwerden, beim Gewaltgebrauch ist der Effekt unklar und am ehesten bei eng begrenztem Ermessen über das Einschalten zu erwarten.', 'gemischt', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'land', null, true, 'blind'),
  (9639, 34, 'Deeskalation und Kommunikation in Ausbildung und Einsatzpraxis der Polizei stärken (Land)', 'Ein Feldexperiment (Louisville) fand nach Deeskalationstraining 28 % weniger Gewaltanwendung, ein Training zu fairem Auftreten wirkte in drei US-Städten. Insgesamt gibt es nur wenige belastbare Studien.', 'gemischt', 'https://crimesolutions.ojp.gov/ratedprograms/integrating-communications-assessment-and-tactics-icat-de-escalation-training', 'land', null, true, 'blind'),
  (9640, 34, 'Antidiskriminierungs-, Demokratie- und interkulturelle Bildung in der Polizeiausbildung (Land)', 'Schulungen erhöhen Wissen und Problembewusstsein; eine große Auswertung beim NYPD fand aber keine messbare Änderung im Kontrollverhalten. Die Wirkung auf den Umgang im Einsatz ist unsicher.', 'gemischt', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'land', null, true, 'blind'),
  (9641, 34, 'Polizeiaus- und -fortbildung allgemein modernisieren und stärken (Land)', 'Bessere Ausbildung kann den Umgang mit Menschen verbessern; ohne Inhalte wie Kommunikation oder Deeskalation bleibt offen, ob sie an respektvollem Verhalten ansetzt. Zur Wirkung gibt es kaum Untersuchungen.', 'offen', null, 'land', null, true, 'blind'),
  (9642, 34, 'Gemeinsame Einsätze von Polizei und psychosozialen Fachkräften bei psychischen Krisen (Land)', 'Gemeinsame Teams können Zwangsmaßnahmen und Gewahrsam verringern; ein Review fand aber keine randomisierten Studien und uneinheitliche Modelle. Betrifft nur Krisensituationen, Fachpersonal ist knapp.', 'gemischt', 'https://oxfordhealth.nhs.uk/orka/title/a-systematic-review-of-co-responder-models-of-police-mental-health-street-triage/', 'land', null, true, 'blind'),
  (9643, 34, 'Bürgernahe Polizei mit festen Ansprechpersonen und Präsenz im Quartier (Land)', 'Ein Campbell-Review zeigt, dass bürgernahe Polizeiarbeit Zufriedenheit und wahrgenommene Legitimität erhöht, Kriminalität aber kaum senkt. Erfordert zusätzliches Personal, das vielerorts fehlt.', 'belegt', 'https://cris.huji.ac.il/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'land', null, true, 'blind'),
  (9644, 34, 'Fehlerkultur, Supervision und Einsatznachbereitung in der Polizei ausbauen (Land)', 'Regelmäßige Reflexion von Einsätzen kann Fehler im Umgang erkennbar machen; ob sie das Verhalten in Kontrollen messbar verändert, ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9645, 34, 'Disziplinarverfahren bei Fehlverhalten beschleunigen und konsequent durchsetzen (Land)', 'Schnellere und konsequente Disziplinarverfahren geben Fehlverhalten Folgen; an der unabhängigen Aufklärung von Vorwürfen ändert das wenig. Zur Wirkung gibt es kaum Studien.', 'offen', null, 'land', null, true, 'blind'),
  (9646, 34, 'Schulungen zu Diskriminierung, Diversität und Fehlerkultur in der Polizeiausbildung (Bund)', 'Schulungen erhöhen Problembewusstsein; beim NYPD war danach aber keine Änderung im Kontrollverhalten messbar. Der Bund regelt das nur für die Bundespolizei, für die Landespolizeien kann er nur anregen.', 'gemischt', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'bund', null, true, 'blind'),
  (9647, 34, 'Bodycams bei der Polizei einsetzen (Bund)', 'Bodycams können Beweise sichern und Beschwerden senken; ohne Einschaltpflicht oder Zugriff Betroffener bleibt die Wirkung laut Review gering. Der Bund regelt nur die Bundespolizei.', 'gemischt', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'bund', null, true, 'blind'),
  (9648, 34, 'Polizeibeauftragte des Bundes abschaffen (Bund)', 'Entfernt eine unabhängige Anlaufstelle für Beschwerden; die Klärung bliebe bei Staatsanwaltschaften, deren Verfahren häufig eingestellt werden. Die Stelle wirkt bisher begrenzt, ein Ersatz ist nicht vorgesehen.', 'gemischt', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 34 and id not in (9631, 9632, 9633, 9634, 9635, 9636, 9637, 9638, 9639, 9640, 9641, 9642, 9643, 9644, 9645, 9646, 9647, 9648);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9649, 34, 11, null, 'Vorwürfe gegen Sicherheitsbehörden nur durch Staatsanwaltschaften und Gerichte klären; den Polizeibeauftragten des Bundes abschaffen', '{3403}', 9648, 0, 3, null, 'Entfernt eine unabhängige Anlaufstelle für Beschwerden; die Klärung bliebe bei Staatsanwaltschaften, deren Verfahren häufig eingestellt werden. Die Stelle wirkt bisher begrenzt, ein Ersatz ist nicht vorgesehen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9650, 34, 11, null, 'Polizei mit Bodycams ausstatten, auch für Einsätze in Wohnräumen', '{3403}', 9647, 1, 2, null, 'Bodycams können Beweise sichern und Beschwerden senken; ohne Einschaltpflicht oder Zugriff Betroffener bleibt die Wirkung laut Review gering. Der Bund regelt nur die Bundespolizei.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9651, 34, 11, 'BE', 'Kriminalitätsauffällige Räume sollen kurzfristig zu kriminalitätsbelasteten Orten erklärt werden können, an denen verdachtsunabhängige Personenkontrollen möglich sind.', '{3401}', 9634, 0, 3, null, 'Mehr Kontrollen erhöhen die Zahl der Kontakte, die in Studien mit psychischer Belastung junger Menschen zusammenhängen; für respektvolle, verhältnismäßige Kontakte hilft das nicht. Ziel ist Sicherheit, nicht der Umgang.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'belegt', '2026-10-08', false, true, 'blind'),
  (9652, 34, 11, 'BE', 'Kooperation von Schulen mit der Polizei ausbauen und regelmäßige Blaulicht-Tage an Schulen einführen, auch um Distanz zu Vertretern des Staates abzubauen.', '{3402}', null, 1, 3, null, 'Begegnungen in Schulen können Distanz abbauen und Vertrauen fördern, verändern aber nicht das Verhalten bei Kontrollen; die Wirkung ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=64', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9653, 34, 11, 'BE', 'Petitionsausschuss stärken und Doppelstrukturen mit dem Bürger- und Polizeibeauftragten abbauen.', '{3403}', null, 0, 3, null, 'Ein gestärkter Petitionsausschuss ist eine Beschwerdemöglichkeit, hat aber weniger Untersuchungsbefugnisse; der Abbau beim Polizeibeauftragten schwächt die unabhängige Kontrolle.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=118', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9654, 34, 11, 'MV', 'Höheren Kontrolldruck in Innenstädten und an Kriminalitätsschwerpunkten sowie wirksamere Platzverweise und Aufenthaltsverbote', '{3401}', 9634, 0, 3, null, 'Mehr Kontrollen erhöhen die Zahl der Kontakte, die in Studien mit psychischer Belastung junger Menschen zusammenhängen; für respektvolle, verhältnismäßige Kontakte hilft das nicht. Ziel ist Sicherheit, nicht der Umgang.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=31', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'belegt', '2026-10-08', false, true, 'blind'),
  (9655, 34, 11, 'MV', 'Ausbildung des mittleren Polizeivollzugsdienstes analysieren, Ausbildungsinhalte modernisieren und digital aufbereiten', '{3402}', 9641, 1, 3, null, 'Bessere Ausbildung kann den Umgang mit Menschen verbessern; ohne Inhalte wie Kommunikation oder Deeskalation bleibt offen, ob sie an respektvollem Verhalten ansetzt. Zur Wirkung gibt es kaum Untersuchungen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=28', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9656, 34, 11, 'ST', 'Bodycam-Einsatz der Polizei rechtlich auch in Wohnungen ermöglichen, wegen der deeskalierenden Wirkung etwa bei häuslicher Gewalt', '{3403}', null, 1, 2, null, 'Erweitert Aufnahmen auf Wohnungen, vor allem zum Schutz der Beamten; ohne Einschaltpflicht oder Zugriff Betroffener bleibt der Beitrag zur Klärung von Vorwürfen laut Review gering. Art. 13 GG setzt enge Grenzen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9657, 34, 12, 'BE', 'Verdachtsunabhängige Kontrollen räumlich und im Anwendungsbereich auf das notwendige Minimum beschränken', '{3401}', 9632, 2, 3, null, 'Weniger anlasslose Kontrollen senken die Zahl belastender Kontakte, die in Studien mit Stress und Angst junger Menschen zusammenhängen. Kontrollen mit Verdacht bleiben, daher ist nur ein Teil der Kontakte betroffen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'belegt', '2026-10-08', false, true, 'blind'),
  (9658, 34, 12, 'BE', 'Einstufung kriminalitätsbelasteter Orte regelmäßig parlamentarisch kontrollieren', '{3401}', 9633, 1, 3, null, 'Klare, öffentliche Kriterien und Kontrolle durch das Parlament können die Ausweisung solcher Orte begrenzen; die Befugnis zu anlasslosen Kontrollen bleibt aber bestehen. Zur Wirkung gibt es kaum Untersuchungen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9659, 34, 12, 'BE', 'Interkulturelle Kompetenz der Polizei ausbauen, Sensibilisierung für Rassismus, Queerfeindlichkeit und geschlechtsspezifische Gewalt in Aus- und Fortbildung stärken', '{3402}', 9640, 1, 3, null, 'Schulungen erhöhen Wissen und Problembewusstsein; eine große Auswertung beim NYPD fand aber keine messbare Änderung im Kontrollverhalten. Die Wirkung auf den Umgang im Einsatz ist unsicher.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9660, 34, 12, 'BE', 'Routinemäßige Supervision ausbauen, in der Polizeikräfte das Einsatzgeschehen reflektieren', '{3402}', 9644, 1, 3, null, 'Regelmäßige Reflexion von Einsätzen kann Fehler im Umgang erkennbar machen; ob sie das Verhalten in Kontrollen messbar verändert, ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9661, 34, 12, 'BE', 'Community Policing: Polizeiarbeit mit Bündnisarbeit im Quartier verbinden, dazu ein digitales Programm, das junge Menschen online erreicht', '{3402}', 9643, 2, 2, null, 'Ein Campbell-Review zeigt, dass bürgernahe Polizeiarbeit Zufriedenheit und wahrgenommene Legitimität erhöht, Kriminalität aber kaum senkt. Erfordert zusätzliches Personal, das vielerorts fehlt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', 'https://cris.huji.ac.il/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9662, 34, 12, 'BE', 'Polizei, sozialpädagogische Fachkräfte und sozialpsychiatrische Dienste für Einsätze bei Menschen in psychischen Krisen vernetzen', '{3402}', 9642, 2, 2, null, 'Gemeinsame Teams können Zwangsmaßnahmen und Gewahrsam verringern; ein Review fand aber keine randomisierten Studien und uneinheitliche Modelle. Betrifft nur Krisensituationen, Fachpersonal ist knapp.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', 'https://oxfordhealth.nhs.uk/orka/title/a-systematic-review-of-co-responder-models-of-police-mental-health-street-triage/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9663, 34, 12, 'BE', 'Einheit „Interne Ermittlungen“ bei der Innenverwaltung für strafrechtliche Vorwürfe gegen Beschäftigte des öffentlichen Dienstes', '{3403}', null, 1, 3, null, 'Eine eigene Ermittlungseinheit bündelt Fachwissen, bleibt aber in der Innenverwaltung und damit nahe an der Polizei; ob sie weniger Verfahren scheitern lässt, ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9664, 34, 12, 'BE', 'Auf Bundesebene die Rechte des unabhängigen Polizei- und Bürgerbeauftragten im Strafprozess stärken', '{3403}', null, 1, 1, null, 'Akteneinsicht für Polizeibeauftragte im Strafprozess empfiehlt eine Analyse; die Stellen bleiben aber auf polizeiliche Ermittlungen angewiesen. Ein Land kann das nur über den Bund (StPO) anstoßen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9665, 34, 12, 'MV', 'Interkulturelle Öffnung und interkulturelle Kompetenz der Verwaltung fortführen, ausdrücklich auch in der Polizei', '{3402}', 9640, 1, 3, null, 'Schulungen erhöhen Wissen und Problembewusstsein; eine große Auswertung beim NYPD fand aber keine messbare Änderung im Kontrollverhalten. Die Wirkung auf den Umgang im Einsatz ist unsicher.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=39', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9666, 34, 12, 'ST', 'Unabhängigkeit des Polizeibeauftragten stärken', '{3403}', 9635, 2, 3, null, 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=29', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9667, 34, 12, 'ST', 'Aus- und Fortbildung der Polizei modernisieren und an neue Einsatzlagen anpassen', '{3402}', 9641, 1, 3, null, 'Bessere Ausbildung kann den Umgang mit Menschen verbessern; ohne Inhalte wie Kommunikation oder Deeskalation bleibt offen, ob sie an respektvollem Verhalten ansetzt. Zur Wirkung gibt es kaum Untersuchungen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=29', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9668, 34, 12, 'ST', 'Rassismuskritische Bildungsarbeit in der Polizei (sowie Verwaltung und Schulen) ausbauen', '{3402}', 9640, 1, 3, null, 'Schulungen erhöhen Wissen und Problembewusstsein; eine große Auswertung beim NYPD fand aber keine messbare Änderung im Kontrollverhalten. Die Wirkung auf den Umgang im Einsatz ist unsicher.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9669, 34, 13, null, 'Ticketsystem für polizeiliche Kontrollen einführen, das die Gründe der Kontrolle darlegt', '{3401}', null, 2, 2, null, 'Ein Beleg mit Kontrollgrund macht Kontrollen nachprüfbar; in Spanien sanken mit Formularen und Auswertung Kontrollzahl und Ungleichbehandlung. Der Bund kann das nur für die Bundespolizei regeln.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', 'https://liberties.eu/en/news/stop-forms-ethnic-profiling-spain/16436', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9670, 34, 13, null, 'Polizeibeauftragten des Bundes als Anlaufstelle für Polizeikräfte und Bürgerinnen und Bürger stärken und weiterentwickeln', '{3403}', null, 2, 3, null, 'Stärkt eine bestehende unabhängige Anlaufstelle; Polizeibeauftragte erreichen laut Analyse viele Betroffene kaum und haben begrenzte Befugnisse. Gilt nur für Polizeien des Bundes.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9671, 34, 13, null, 'Anonymisierte Kennzeichnungspflicht für die Bundespolizei einführen', '{3403}', null, 2, 3, null, 'Erkennbare Beamte sind Voraussetzung, um Vorwürfe zuzuordnen; der EGMR rügte 2017 unter anderem fehlende Identifizierbarkeit. Für die Bundespolizei kann der Bund das selbst regeln, Wirkungsstudien fehlen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9672, 34, 13, null, 'In der Aus- und Fortbildung der Polizei für Diversität sensibilisieren und eine gute Fehlerkultur entwickeln', '{3402}', 9646, 1, 2, null, 'Schulungen erhöhen Problembewusstsein; beim NYPD war danach aber keine Änderung im Kontrollverhalten messbar. Der Bund regelt das nur für die Bundespolizei, für die Landespolizeien kann er nur anregen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9673, 34, 13, 'BE', 'Digitale Kontrollquittung einführen, die Kontrollierte über den Anlass der Polizeikontrolle informiert; anlasslose Kontrollen werden abgelehnt', '{3401}', 9631, 2, 3, null, 'Ein schriftlicher Kontrollgrund macht Kontrollen nachprüfbar; in Fuenlabrada (Spanien) sanken Kontrollzahl und Ungleichbehandlung, dort aber zusammen mit Schulung und Datenauswertung. Ohne Auswertung bleibt die Wirkung unsicher.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=228', 'https://liberties.eu/en/news/stop-forms-ethnic-profiling-spain/16436', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9674, 34, 13, 'BE', 'Bestehende kriminalitätsbelastete Orte sowie Messer- und Waffenverbotszonen überprüfen und, wo erforderlich, wieder abschaffen', '{3401}', 9632, 2, 3, null, 'Weniger anlasslose Kontrollen senken die Zahl belastender Kontakte, die in Studien mit Stress und Angst junger Menschen zusammenhängen. Kontrollen mit Verdacht bleiben, daher ist nur ein Teil der Kontakte betroffen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=228', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'belegt', '2026-10-08', false, true, 'blind'),
  (9675, 34, 13, 'BE', 'Ergebnisse der Bodycam-Studie umsetzen; Bodycam muss auf Verlangen oder bei unmittelbarem Zwang zur Beweissicherung eingeschaltet werden', '{3403}', 9638, 2, 3, null, 'Aufnahmen sichern Beweise für die Klärung von Vorwürfen; laut Campbell-Review sinken Beschwerden, beim Gewaltgebrauch ist der Effekt unklar und am ehesten bei eng begrenztem Ermessen über das Einschalten zu erwarten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=228', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9676, 34, 13, 'BE', 'Unabhängige Kontrolle durch den Bürger- und Polizeibeauftragten verbessern, damit er alle an ihn herangetragenen Sachverhalte effektiv überprüfen kann', '{3403}', 9635, 2, 3, null, 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=227', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9677, 34, 13, 'BE', 'Demokratiebildung, Diskriminierungskritik und kommunikative Kompetenzen in Aus- und Fortbildung sowie Studium der Sicherheitsbehörden fördern', '{3402}', 9639, 2, 3, null, 'Ein Feldexperiment (Louisville) fand nach Deeskalationstraining 28 % weniger Gewaltanwendung, ein Training zu fairem Auftreten wirkte in drei US-Städten. Insgesamt gibt es nur wenige belastbare Studien.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=226', 'https://crimesolutions.ojp.gov/ratedprograms/integrating-communications-assessment-and-tactics-icat-de-escalation-training', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9678, 34, 13, 'BE', 'Empfehlungen der Berliner Polizeistudie umsetzen und Supervision, Einsatznachbereitung und Resilienzstärkung ausbauen', '{3402}', 9644, 1, 3, null, 'Regelmäßige Reflexion von Einsätzen kann Fehler im Umgang erkennbar machen; ob sie das Verhalten in Kontrollen messbar verändert, ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=226', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9679, 34, 13, 'BE', 'Community Policing in die Fläche bringen: mehr Kontaktbereichsbeamte als lokale Ansprechpersonen, Fahrradstreifen, mobile Wachen', '{3402}', 9643, 2, 2, null, 'Ein Campbell-Review zeigt, dass bürgernahe Polizeiarbeit Zufriedenheit und wahrgenommene Legitimität erhöht, Kriminalität aber kaum senkt. Erfordert zusätzliches Personal, das vielerorts fehlt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=225', 'https://cris.huji.ac.il/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9680, 34, 13, 'BE', 'Kurswechsel zu einer Deeskalationsstrategie der Polizei bei Versammlungen', '{3402}', 9639, 2, 3, null, 'Ein Feldexperiment (Louisville) fand nach Deeskalationstraining 28 % weniger Gewaltanwendung, ein Training zu fairem Auftreten wirkte in drei US-Städten. Insgesamt gibt es nur wenige belastbare Studien.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=229', 'https://crimesolutions.ojp.gov/ratedprograms/integrating-communications-assessment-and-tactics-icat-de-escalation-training', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9681, 34, 13, 'MV', 'Aus- und Fortbildung der Landespolizei reformieren: mehr politische Bildung, bessere Vorbereitung auf Einsätze mit Menschen in psychischen Ausnahmezuständen', '{3402}', 9639, 2, 3, null, 'Ein Feldexperiment (Louisville) fand nach Deeskalationstraining 28 % weniger Gewaltanwendung, ein Training zu fairem Auftreten wirkte in drei US-Städten. Insgesamt gibt es nur wenige belastbare Studien.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', 'https://crimesolutions.ojp.gov/ratedprograms/integrating-communications-assessment-and-tactics-icat-de-escalation-training', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9682, 34, 13, 'MV', 'Bürgernahe Polizei nach skandinavischem Vorbild stärken: mehr Präsenz vor Ort, Fußstreifen in den Quartieren, direkter Dialog mit den Menschen', '{3402}', 9643, 2, 2, null, 'Ein Campbell-Review zeigt, dass bürgernahe Polizeiarbeit Zufriedenheit und wahrgenommene Legitimität erhöht, Kriminalität aber kaum senkt. Erfordert zusätzliches Personal, das vielerorts fehlt.', 'https://gruene-mv.de/?wpdmdl=33772#page=76', 'https://cris.huji.ac.il/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9683, 34, 13, 'MV', 'Im Polizeigesetz verpflichtenden Einsatz von Bodycams bei Androhung und Anwendung körperlicher Gewalt vorsehen', '{3403}', 9638, 2, 3, null, 'Aufnahmen sichern Beweise für die Klärung von Vorwürfen; laut Campbell-Review sinken Beschwerden, beim Gewaltgebrauch ist der Effekt unklar und am ehesten bei eng begrenztem Ermessen über das Einschalten zu erwarten.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9684, 34, 13, 'MV', 'Unabhängige Polizeibeauftragte Stelle schaffen, an die sich Bürgerinnen und Bürger sowie Polizeikräfte mit Hinweisen und Beschwerden wenden können', '{3403}', 9635, 2, 3, null, 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9685, 34, 13, 'MV', 'Numerische Kennzeichnungspflicht auf alle Einsatzlagen und alle eingesetzten Polizeikräfte ausweiten', '{3403}', 9637, 2, 3, null, 'Erkennbare Beamte sind Voraussetzung, um Vorwürfe einer Person zuzuordnen; der EGMR rügte 2017 unter anderem fehlende Identifizierbarkeit. Wirkungsstudien gibt es kaum, viele Länder haben die Pflicht bereits.', 'https://gruene-mv.de/?wpdmdl=33772#page=78', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9686, 34, 13, 'ST', 'Aus- und Fortbildung der Polizei auf Menschenrechte, Antidiskriminierung, interkulturelle Kompetenz und Deeskalation ausrichten, mit regelmäßigen Fortbildungen', '{3402}', 9639, 2, 3, null, 'Ein Feldexperiment (Louisville) fand nach Deeskalationstraining 28 % weniger Gewaltanwendung, ein Training zu fairem Auftreten wirkte in drei US-Städten. Insgesamt gibt es nur wenige belastbare Studien.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', 'https://crimesolutions.ojp.gov/ratedprograms/integrating-communications-assessment-and-tactics-icat-de-escalation-training', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9687, 34, 13, 'ST', 'Polizeihochschule zu einer unabhängigen Hochschule mit Forschung, Veröffentlichungen und externen Lehrenden weiterentwickeln', '{3402}', 9641, 1, 3, null, 'Bessere Ausbildung kann den Umgang mit Menschen verbessern; ohne Inhalte wie Kommunikation oder Deeskalation bleibt offen, ob sie an respektvollem Verhalten ansetzt. Zur Wirkung gibt es kaum Untersuchungen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9688, 34, 13, 'ST', 'Unabhängige Polizeibeauftragte Stelle schaffen, die Beschwerden und Fehlverhalten niedrigschwellig mit umfassenden Rechten untersucht und jährlich dem Landtag berichtet', '{3403}', 9635, 2, 3, null, 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9689, 34, 13, 'ST', 'Klare, gut zugängliche Beschwerdewege bei der Polizei; Beschwerden nachvollziehbar dokumentieren und auswerten', '{3403}', null, 1, 3, null, 'Klare, dokumentierte Beschwerdewege erleichtern Beschwerden und lassen Muster erkennen; ohne unabhängige Prüfung bleibt die Klärung bei der Polizei selbst. Zur Wirkung gibt es kaum Studien.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9690, 34, 13, 'ST', 'Gezielt Menschen mit Migrationsgeschichte, Frauen, queere Menschen und Mehrsprachige für die Polizei ansprechen und fördern, auch für bessere Kommunikation in Einsätzen', '{3402}', null, 1, 3, null, 'In Chicago kontrollierten Beamte aus Minderheiten und Frauen seltener und nutzten seltener Gewalt; Nachwuchswerbung verändert die Zusammensetzung aber nur langsam, Ergebnisse anderswo sind uneinheitlich.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', 'https://collaborate.princeton.edu/en/publications/the-role-of-officer-race-and-gender-in-police-civilian-interactio/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9691, 34, 14, 'BE', 'Kriterien für kriminalitätsbelastete Orte (mit verdachtsunabhängigen Kontrollen) präzisieren, öffentlich nachvollziehbar machen und im ASOG mit einer Straftatenliste festlegen', '{3401}', 9633, 1, 3, null, 'Klare, öffentliche Kriterien und Kontrolle durch das Parlament können die Ausweisung solcher Orte begrenzen; die Befugnis zu anlasslosen Kontrollen bleibt aber bestehen. Zur Wirkung gibt es kaum Untersuchungen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9692, 34, 14, 'BE', 'Kontaktbereichsbeamtinnen und -beamte intensiver einsetzen und entlasten, um den niedrigschwelligen Austausch zwischen Polizei und Bevölkerung zu verbessern', '{3402}', 9643, 2, 2, null, 'Ein Campbell-Review zeigt, dass bürgernahe Polizeiarbeit Zufriedenheit und wahrgenommene Legitimität erhöht, Kriminalität aber kaum senkt. Erfordert zusätzliches Personal, das vielerorts fehlt.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', 'https://cris.huji.ac.il/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9693, 34, 14, 'MV', 'Pseudonymisierte Kennzeichnungspflicht für alle Polizeikräfte bei Einsätzen einführen', '{3403}', 9637, 2, 3, null, 'Erkennbare Beamte sind Voraussetzung, um Vorwürfe einer Person zuzuordnen; der EGMR rügte 2017 unter anderem fehlende Identifizierbarkeit. Wirkungsstudien gibt es kaum, viele Länder haben die Pflicht bereits.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9694, 34, 14, 'MV', 'Polizeibeauftragten als unabhängige Anlaufstelle für Beschwerden von Bürgern und für Polizeibeschäftigte stärken', '{3403}', 9635, 2, 3, null, 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9695, 34, 14, 'MV', 'Aus- und Fortbildung der Polizei auf hohem Niveau sichern und die Fachhochschule in Güstrow personell und finanziell stärken', '{3402}', 9641, 1, 3, null, 'Bessere Ausbildung kann den Umgang mit Menschen verbessern; ohne Inhalte wie Kommunikation oder Deeskalation bleibt offen, ob sie an respektvollem Verhalten ansetzt. Zur Wirkung gibt es kaum Untersuchungen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9696, 34, 14, 'ST', 'Alle Waffenverbotszonen im Land abschaffen und damit die Möglichkeit anlassloser Personenkontrollen dort beenden', '{3401}', 9632, 2, 3, null, 'Weniger anlasslose Kontrollen senken die Zahl belastender Kontakte, die in Studien mit Stress und Angst junger Menschen zusammenhängen. Kontrollen mit Verdacht bleiben, daher ist nur ein Teil der Kontakte betroffen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=48', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'belegt', '2026-10-08', false, true, 'blind'),
  (9697, 34, 14, 'ST', 'Feste Ansprechpersonen für Antidiskriminierung in der Polizei aufbauen und konsequente, nachhaltige Fortbildung der Polizei', '{3402,3403}', null, 1, 3, null, 'Interne Ansprechpersonen und Fortbildung können Diskriminierung im Umgang ansprechen; sie sind aber nicht unabhängig und die Fortbildung bleibt unbestimmt. Zur Wirkung gibt es kaum Studien.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9698, 34, 15, null, 'Polizeibeauftragte und innerbehördliche Meldestellen abschaffen, ebenso die Beweislastumkehr im Disziplinarverfahren', '{3403}', 9648, 0, 3, null, 'Entfernt eine unabhängige Anlaufstelle für Beschwerden; die Klärung bliebe bei Staatsanwaltschaften, deren Verfahren häufig eingestellt werden. Die Stelle wirkt bisher begrenzt, ein Ersatz ist nicht vorgesehen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=119', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9699, 34, 15, null, 'Razzien und Kontrollstellen in sogenannten No-go-Areas durchführen, um dort den Rechtsstaat durchzusetzen', '{3401}', null, 0, 2, null, 'Mehr Razzien und Kontrollstellen erhöhen die Zahl der Kontrollen, die in Studien mit psychischer Belastung junger Menschen zusammenhängen. Der Bund ist nur für die Bundespolizei zuständig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=123', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'belegt', '2026-10-08', false, true, 'blind'),
  (9700, 34, 15, 'BE', 'Mehr anlasslose Polizeikontrollen in Problemvierteln', '{3401}', 9634, 0, 3, null, 'Mehr Kontrollen erhöhen die Zahl der Kontakte, die in Studien mit psychischer Belastung junger Menschen zusammenhängen; für respektvolle, verhältnismäßige Kontakte hilft das nicht. Ziel ist Sicherheit, nicht der Umgang.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'belegt', '2026-10-08', false, true, 'blind'),
  (9701, 34, 15, 'MV', 'Die im Landespolizeigesetz (SOG) beschlossenen Dokumentationspflichten der Polizei sofort zurücknehmen.', '{3403,3401}', null, 0, 3, null, 'Die Rücknahme von Dokumentationspflichten macht Kontrollen und Einsätze schlechter nachprüfbar; sie entlastet die Polizei von Bürokratie, hilft beim Klären von Fehlern aber nicht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9702, 34, 15, 'MV', 'Disziplinarverfahren der Polizei durch bessere Abläufe und mehr Personal straffen, damit Dienstvergehen schnell geahndet und unberechtigte Vorwürfe schnell ausgeräumt werden.', '{3403}', 9645, 1, 3, null, 'Schnellere und konsequente Disziplinarverfahren geben Fehlverhalten Folgen; an der unabhängigen Aufklärung von Vorwürfen ändert das wenig. Zur Wirkung gibt es kaum Studien.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9703, 34, 15, 'MV', 'Gegen Vorwürfe gegen die Polizei rechtlich vorgehen und Polizisten bei der Verteidigung gegen ungerechtfertigte Vorwürfe unterstützen.', '{3403}', null, 0, 3, null, 'Unterstützt Beamte gegen unberechtigte Vorwürfe, schafft aber keinen besseren Weg, berechtigte Vorwürfe von Betroffenen zu klären.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9704, 34, 15, 'MV', 'Finanzielle Förderung von Vereinen beenden, die der Polizei Rassismus und gewalttätige Übergriffe unterstellen.', '{3403}', null, 0, 3, null, 'Weniger Förderung für Organisationen, die Vorwürfe gegen die Polizei dokumentieren oder Betroffene beraten, schwächt eher die Klärung von Vorwürfen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9705, 34, 15, 'ST', 'Funktion des Polizeibeauftragten des Landes abschaffen; Beschwerden weiter nur über die Zentrale Beschwerdestelle des Innenministeriums', '{3403}', null, 0, 3, null, 'Entfernt eine unabhängige Anlaufstelle; Beschwerden blieben bei einer Stelle im Innenministerium. Polizeibeauftragte wirken laut Analyse bisher begrenzt, eine interne Stelle ist aber weniger unabhängig.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=109', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9706, 34, 15, 'ST', 'Interne Ermittlungen nach Schusswaffengebrauch von Polizeibeamten nur noch bei konkreten Verdachtsmomenten auf Fehlverhalten einleiten', '{3403}', null, 0, 3, null, 'Weniger interne Ermittlungen nach Schusswaffengebrauch schwächen die Klärung möglicher Fehler; das entlastet Beamte, hilft Betroffenen aber nicht.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=106', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9707, 34, 15, 'ST', 'Fördermaßnahmen und Beförderungen von Polizeibeamten erst bei staatsanwaltschaftlichen Ermittlungen aussetzen, nicht schon bei Disziplinarverfahren', '{3403}', null, 0, 3, null, 'Lockert die Folgen von Disziplinarverfahren für Beförderungen; das hilft Betroffenen beim Klären von Fehlern nicht und schwächt eher die Wirkung interner Verfahren.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=108', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9708, 34, 16, null, 'Anlasslose polizeiliche Kontrollbefugnisse abschaffen', '{3401}', null, 2, 2, null, 'Weniger anlasslose Kontrollen senken belastende Kontakte, die in Studien mit Stress junger Menschen zusammenhängen. Der Bund kann das nur für die Bundespolizei regeln, Länderrecht bleibt unberührt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'belegt', '2026-10-08', false, true, 'blind'),
  (9709, 34, 16, null, 'Individuelle Kennzeichnungspflicht für Polizistinnen und Polizisten einführen', '{3403}', null, 2, 2, null, 'Erkennbare Beamte sind Voraussetzung, um Vorwürfe zuzuordnen; der EGMR rügte 2017 unter anderem fehlende Identifizierbarkeit. Wirkungsstudien fehlen, der Bund kann nur die Bundespolizei verpflichten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9710, 34, 16, null, 'Einsatzprotokolle und Polizeivideos zur Aufklärung von Übergriffen bei Treuhandstellen aufbewahren', '{3403}', null, 1, 2, null, 'Aufbewahrung von Protokollen und Videos bei Treuhandstellen schützt Beweise vor Löschung; ohne Aufnahmepflicht und Zugriff Betroffener bleibt der Beitrag begrenzt, die Wirkung ist kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9711, 34, 16, null, 'Einsatz von Pfefferspray durch die Polizei stark einschränken, bei Versammlungen und Ansammlungen im öffentlichen Raum verbieten', '{3402}', null, 1, 2, null, 'Begrenzt Zwangsmittel bei Versammlungen und Ansammlungen und damit unverhältnismäßige Einsätze; betrifft nur einen Ausschnitt der Kontakte, Wirkung kaum untersucht. Der Bund regelt nur die Bundespolizei.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9712, 34, 16, null, 'Polizeiausbildung soll Kenntnisse über gruppenbezogene Menschenfeindlichkeit vermitteln', '{3402}', 9646, 1, 2, null, 'Schulungen erhöhen Problembewusstsein; beim NYPD war danach aber keine Änderung im Kontrollverhalten messbar. Der Bund regelt das nur für die Bundespolizei, für die Landespolizeien kann er nur anregen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9713, 34, 16, 'BE', 'Kriminalitätsbelastete Orte und Waffenverbotszonen mit ihren Sonderbefugnissen wie anlasslosen Kontrollen abschaffen', '{3401}', 9632, 2, 3, null, 'Weniger anlasslose Kontrollen senken die Zahl belastender Kontakte, die in Studien mit Stress und Angst junger Menschen zusammenhängen. Kontrollen mit Verdacht bleiben, daher ist nur ein Teil der Kontakte betroffen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'belegt', '2026-10-08', false, true, 'blind'),
  (9714, 34, 16, 'BE', 'Polizei verpflichten, bei jeder Identitätsfeststellung und Durchsuchung Grund und Rechtsgrundlage schriftlich anzugeben (Kontrollquittung)', '{3401}', 9631, 2, 3, null, 'Ein schriftlicher Kontrollgrund macht Kontrollen nachprüfbar; in Fuenlabrada (Spanien) sanken Kontrollzahl und Ungleichbehandlung, dort aber zusammen mit Schulung und Datenauswertung. Ohne Auswertung bleibt die Wirkung unsicher.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', 'https://liberties.eu/en/news/stop-forms-ethnic-profiling-spain/16436', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9715, 34, 16, 'BE', 'Aus- und Fortbildung der Polizei im Umgang mit Menschen in psychischen Ausnahmesituationen stärken', '{3402}', 9639, 2, 3, null, 'Ein Feldexperiment (Louisville) fand nach Deeskalationstraining 28 % weniger Gewaltanwendung, ein Training zu fairem Auftreten wirkte in drei US-Städten. Insgesamt gibt es nur wenige belastbare Studien.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=291', 'https://crimesolutions.ojp.gov/ratedprograms/integrating-communications-assessment-and-tactics-icat-de-escalation-training', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9716, 34, 16, 'BE', 'Ausbildung der Einsatzkräfte modernisieren und um politische und grundrechtsbezogene Bildung ergänzen', '{3402}', 9640, 1, 3, null, 'Schulungen erhöhen Wissen und Problembewusstsein; eine große Auswertung beim NYPD fand aber keine messbare Änderung im Kontrollverhalten. Die Wirkung auf den Umgang im Einsatz ist unsicher.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=292', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9717, 34, 16, 'BE', 'Polizeiausbildung für den gehobenen Dienst an der Hochschule stärken, mit Fokus auf reflektierte, demokratisch handelnde Beamtinnen und Beamte', '{3402}', 9640, 1, 3, null, 'Schulungen erhöhen Wissen und Problembewusstsein; eine große Auswertung beim NYPD fand aber keine messbare Änderung im Kontrollverhalten. Die Wirkung auf den Umgang im Einsatz ist unsicher.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=293', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9718, 34, 16, 'BE', 'Deeskalationskonzepte bei Versammlungen konsequent verfolgen', '{3402}', 9639, 2, 3, null, 'Ein Feldexperiment (Louisville) fand nach Deeskalationstraining 28 % weniger Gewaltanwendung, ein Training zu fairem Auftreten wirkte in drei US-Städten. Insgesamt gibt es nur wenige belastbare Studien.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=293', 'https://crimesolutions.ojp.gov/ratedprograms/integrating-communications-assessment-and-tactics-icat-de-escalation-training', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9719, 34, 16, 'BE', 'Polizei- und Bürgerbeauftragten ausbauen: mehr Personal, Zugang zu Akten und Bodycam-Aufnahmen, Untersuchungs- und Ermittlungsbefugnisse bei Polizeigewalt', '{3403}', 9635, 2, 3, null, 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9720, 34, 16, 'BE', 'Bürger können Bodycam-Aktivierung verlangen und Aufnahmen einsehen; Hinweispflicht der Polizei, automatische Auslösung beim Waffeneinsatz', '{3403}', 9638, 2, 3, null, 'Aufnahmen sichern Beweise für die Klärung von Vorwürfen; laut Campbell-Review sinken Beschwerden, beim Gewaltgebrauch ist der Effekt unklar und am ehesten bei eng begrenztem Ermessen über das Einschalten zu erwarten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9721, 34, 16, 'BE', 'Rechtslage klarstellen, damit alle Bürgerinnen und Bürger Polizeieinsätze filmen dürfen', '{3403}', null, 1, 1, null, 'Aufnahmen von Bürgerinnen und Bürgern können Beweise liefern; ob Filmen erlaubt ist, hängt aber vor allem am Bundesrecht (StGB, Kunsturhebergesetz), das ein Land nicht klarstellen kann.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9722, 34, 16, 'MV', 'Kontrollquittungen für Personen einführen, die von polizeilichen Maßnahmen betroffen sind.', '{3401}', 9631, 2, 3, null, 'Ein schriftlicher Kontrollgrund macht Kontrollen nachprüfbar; in Fuenlabrada (Spanien) sanken Kontrollzahl und Ungleichbehandlung, dort aber zusammen mit Schulung und Datenauswertung. Ohne Auswertung bleibt die Wirkung unsicher.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=19', 'https://liberties.eu/en/news/stop-forms-ethnic-profiling-spain/16436', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9723, 34, 16, 'MV', 'Den Polizeibeauftragten des Landes zu einer Anlaufstelle für alle Menschen ausbauen.', '{3403}', 9635, 2, 3, null, 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9724, 34, 16, 'MV', 'Eine von der Polizei unabhängige Beschwerdestelle mit ausreichendem Mandat, Ressourcen und Befugnissen schaffen, um Fehlverhalten der Polizei zu verfolgen und aufzuklären.', '{3403}', 9635, 2, 3, null, 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9725, 34, 16, 'MV', 'Demokratie- und Grundrechtsbildung in Aus- und Fortbildung der Polizei stärken und eine Fehlerkultur fördern.', '{3402}', 9640, 1, 3, null, 'Schulungen erhöhen Wissen und Problembewusstsein; eine große Auswertung beim NYPD fand aber keine messbare Änderung im Kontrollverhalten. Die Wirkung auf den Umgang im Einsatz ist unsicher.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9726, 34, 16, 'ST', 'Unabhängige Polizeibeschwerdestelle mit eigenen Ermittlungsbefugnissen und ausreichender Ausstattung schaffen', '{3403}', 9635, 2, 3, null, 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9727, 34, 16, 'ST', 'Individuelle Kennzeichnungspflicht für Polizeikräfte', '{3403}', 9637, 2, 3, null, 'Erkennbare Beamte sind Voraussetzung, um Vorwürfe einer Person zuzuordnen; der EGMR rügte 2017 unter anderem fehlende Identifizierbarkeit. Wirkungsstudien gibt es kaum, viele Länder haben die Pflicht bereits.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=129', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9728, 34, 16, 'ST', 'Bodycams automatisch einschalten, wenn Schusswaffen oder Taser eingesetzt werden, um Einsätze zu dokumentieren', '{3403}', 9638, 2, 3, null, 'Aufnahmen sichern Beweise für die Klärung von Vorwürfen; laut Campbell-Review sinken Beschwerden, beim Gewaltgebrauch ist der Effekt unklar und am ehesten bei eng begrenztem Ermessen über das Einschalten zu erwarten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=129', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9729, 34, 16, 'ST', 'Regelmäßige Fortbildungen der Polizei zu Menschenrechten und interkultureller Kompetenz', '{3402}', 9640, 1, 3, null, 'Schulungen erhöhen Wissen und Problembewusstsein; eine große Auswertung beim NYPD fand aber keine messbare Änderung im Kontrollverhalten. Die Wirkung auf den Umgang im Einsatz ist unsicher.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9730, 34, 16, 'ST', 'Präventionspolizei mit spezialisierten Beamtinnen und Beamten stärken, die in Schulen, Vereinen und Gemeinden langfristig Vertrauen aufbauen', '{3402}', 9643, 2, 2, null, 'Ein Campbell-Review zeigt, dass bürgernahe Polizeiarbeit Zufriedenheit und wahrgenommene Legitimität erhöht, Kriminalität aber kaum senkt. Erfordert zusätzliches Personal, das vielerorts fehlt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', 'https://cris.huji.ac.il/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9731, 34, 17, null, 'Polizei mit moderner Ausstattung versehen und dabei auf exzellente Aus- und Fortbildung in Akademien und Trainingszentren setzen', '{3402}', null, 1, 2, null, 'Gute Aus- und Fortbildung kann den Umgang verbessern, Inhalte wie Kommunikation werden aber nicht genannt; Ausstattung zählt zur Sicherheit. Der Bund kann das nur für die Bundespolizei regeln.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9732, 34, 17, 'BE', 'Einsatzkräfte stärker in Deeskalation schulen; bestehende Deeskalationsstrategien bei Demonstrationen konsequent anwenden und auswerten', '{3402}', 9639, 2, 3, null, 'Ein Feldexperiment (Louisville) fand nach Deeskalationstraining 28 % weniger Gewaltanwendung, ein Training zu fairem Auftreten wirkte in drei US-Städten. Insgesamt gibt es nur wenige belastbare Studien.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', 'https://crimesolutions.ojp.gov/ratedprograms/integrating-communications-assessment-and-tactics-icat-de-escalation-training', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9733, 34, 17, 'BE', 'Bei unverhältnismäßiger Polizeigewalt sofortige Disziplinarmaßnahmen und Überprüfung der Einsatzkräfte, bei schweren oder wiederholten Fehltritten bis zur Entfernung aus dem Dienst', '{3403}', 9645, 1, 3, null, 'Schnellere und konsequente Disziplinarverfahren geben Fehlverhalten Folgen; an der unabhängigen Aufklärung von Vorwürfen ändert das wenig. Zur Wirkung gibt es kaum Studien.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9734, 34, 17, 'BE', 'Zusätzliche gemeinsame Kontrollen von Ordnungsamt, Polizei und Zoll gegen Drogenmissbrauch, in Innenräumen und im öffentlichen Raum', '{3401}', 9634, 0, 3, null, 'Mehr Kontrollen erhöhen die Zahl der Kontakte, die in Studien mit psychischer Belastung junger Menschen zusammenhängen; für respektvolle, verhältnismäßige Kontakte hilft das nicht. Ziel ist Sicherheit, nicht der Umgang.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', 'https://nij.ojp.gov/library/publications/aggressive-policing-and-mental-health-young-urban-men', 'belegt', '2026-10-08', false, true, 'blind'),
  (9735, 34, 17, 'MV', 'Fehlerkultur und Qualitätssicherung bei der Polizei durch praxisnahe Fortbildung und klare Standards für die Nachbereitung von Einsätzen', '{3402}', 9644, 1, 3, null, 'Regelmäßige Reflexion von Einsätzen kann Fehler im Umgang erkennbar machen; ob sie das Verhalten in Kontrollen messbar verändert, ist kaum untersucht.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=68', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9736, 34, 18, null, 'Polizei, Verwaltung und Justiz werden durch unabhängige Kontrollstellen überwacht, die Fehlverhalten transparent aufarbeiten', '{3403}', null, 2, 2, null, 'Unabhängige Kontrollstellen setzen an der Klärung von Vorwürfen an; Ausgestaltung und Befugnisse bleiben offen, die Wirkung bestehender Stellen ist uneinheitlich. Der Bund kann nur für seine Behörden handeln.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=143', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9737, 34, 18, null, 'Unabhängige Beschwerdestellen gegen Diskriminierung (auch durch Sicherheitsbehörden) ausbauen', '{3403}', null, 1, 2, null, 'Unabhängige Antidiskriminierungsstellen können auch Beschwerden über Polizeikontakte aufnehmen, haben aber meist keine Befugnisse gegenüber der Polizei; der Bund kann vor allem fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=37', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9738, 34, 18, null, 'Bodycams und Personalrotation bei Polizei und anderen Institutionen einsetzen, um Transparenz zu sichern', '{3403}', 9647, 1, 2, null, 'Bodycams können Beweise sichern und Beschwerden senken; ohne Einschaltpflicht oder Zugriff Betroffener bleibt die Wirkung laut Review gering. Der Bund regelt nur die Bundespolizei.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=143', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9739, 34, 18, null, 'Verpflichtende Schulungen für Sicherheitskräfte, um unbewusste Diskriminierung zu erkennen und zu verhindern', '{3402}', 9646, 1, 2, null, 'Schulungen erhöhen Problembewusstsein; beim NYPD war danach aber keine Änderung im Kontrollverhalten messbar. Der Bund regelt das nur für die Bundespolizei, für die Landespolizeien kann er nur anregen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=37', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9740, 34, 18, null, 'Begegnungsräume zwischen Polizei, migrantischen Communities und Sozialarbeit schaffen, um Vorurteile abzubauen', '{3402}', null, 1, 2, null, 'Begegnungsräume können Vorurteile abbauen und Vertrauen stärken; die Wirkung auf das Verhalten in Kontrollen ist kaum untersucht, der Bund kann vor allem fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=143', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9741, 34, 18, 'BE', 'Polizeiausbildung anheben: bessere Auswahlverfahren, kleinere Ausbildungsgruppen und verpflichtende Weiterbildungen', '{3402}', 9641, 1, 3, null, 'Bessere Ausbildung kann den Umgang mit Menschen verbessern; ohne Inhalte wie Kommunikation oder Deeskalation bleibt offen, ob sie an respektvollem Verhalten ansetzt. Zur Wirkung gibt es kaum Untersuchungen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=77', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9742, 34, 18, 'BE', 'Pflichtschulungen der Polizei zu Rassismus und Diskriminierung sowie Training im Umgang mit vulnerablen Gruppen, um Konflikteskalationen zu vermeiden', '{3402}', 9639, 2, 3, null, 'Ein Feldexperiment (Louisville) fand nach Deeskalationstraining 28 % weniger Gewaltanwendung, ein Training zu fairem Auftreten wirkte in drei US-Städten. Insgesamt gibt es nur wenige belastbare Studien.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=77', 'https://crimesolutions.ojp.gov/ratedprograms/integrating-communications-assessment-and-tactics-icat-de-escalation-training', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9743, 34, 18, 'BE', 'Gemeinsame mobile Street-Triage-Teams aus Polizei und Krisendienst, geschult in Deeskalation, für Einsätze bei Menschen in psychischen Krisen', '{3402}', 9642, 2, 2, null, 'Gemeinsame Teams können Zwangsmaßnahmen und Gewahrsam verringern; ein Review fand aber keine randomisierten Studien und uneinheitliche Modelle. Betrifft nur Krisensituationen, Fachpersonal ist knapp.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=83', 'https://oxfordhealth.nhs.uk/orka/title/a-systematic-review-of-co-responder-models-of-police-mental-health-street-triage/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9744, 34, 18, 'BE', 'Bürger- und Polizeibeauftragten als anonyme Meldestelle stärken: Zugang zu Ermittlungsakten und eigene Ermittlungskompetenzen', '{3403}', 9635, 2, 3, null, 'Eine unabhängige Anlaufstelle mit Akteneinsicht macht Beschwerden prüfbar. Laut einer Analyse erreichen die Stellen viele Betroffene kaum, und die strafrechtliche Aufklärung bleibt von Polizeiermittlungen abhängig.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=77', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9745, 34, 18, 'BE', 'Bodycams für alle eingesetzten Kräfte mit Pflicht zum Einschalten bei Einsätzen; Beamte können die Daten nicht selbst löschen', '{3403}', 9638, 2, 3, null, 'Aufnahmen sichern Beweise für die Klärung von Vorwürfen; laut Campbell-Review sinken Beschwerden, beim Gewaltgebrauch ist der Effekt unklar und am ehesten bei eng begrenztem Ermessen über das Einschalten zu erwarten.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=78', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9746, 34, 18, 'MV', 'Unabhängige Ermittlungsstelle für mutmaßliche Polizeigewalt beim Justizministerium einrichten', '{3403}', 9636, 2, 2, null, 'Setzt an der Abhängigkeit der Strafverfahren von polizeilichen Ermittlungen an; ähnliche Stellen gibt es in anderen Staaten. Belastbare Wirkungsstudien fehlen, Aufbau und Personal brauchen Zeit.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9747, 34, 18, 'MV', 'Polizeibeamte zum Einsatz von Bodycams zur Einsatzdokumentation und zum Schutz von Polizei und Bürgern verpflichten', '{3403}', 9638, 2, 3, null, 'Aufnahmen sichern Beweise für die Klärung von Vorwürfen; laut Campbell-Review sinken Beschwerden, beim Gewaltgebrauch ist der Effekt unklar und am ehesten bei eng begrenztem Ermessen über das Einschalten zu erwarten.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9748, 34, 18, 'MV', 'Verbindliche, regelmäßige Antidiskriminierungs-Fortbildungen auch für die Polizei, um diskriminierungssensibel zu handeln und Konflikte professionell zu bearbeiten', '{3402}', 9640, 1, 3, null, 'Schulungen erhöhen Wissen und Problembewusstsein; eine große Auswertung beim NYPD fand aber keine messbare Änderung im Kontrollverhalten. Die Wirkung auf den Umgang im Einsatz ist unsicher.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=18', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9749, 34, 18, 'ST', 'Unabhängige Ermittlungsstelle für mutmaßliche Polizeigewalt beim Justizministerium einrichten', '{3403}', 9636, 2, 2, null, 'Setzt an der Abhängigkeit der Strafverfahren von polizeilichen Ermittlungen an; ähnliche Stellen gibt es in anderen Staaten. Belastbare Wirkungsstudien fehlen, Aufbau und Personal brauchen Zeit.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=170', 'https://hwr-berlin.de/aktuelles/neuigkeiten/neuigkeit-detail/3794-neue-studie-zu-unabhaengigen-polizeibeauftragten/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9750, 34, 18, 'ST', 'Bodycams im Polizeidienst verpflichtend einsetzen, zur Einsatzdokumentation und zum Schutz aller Beteiligten', '{3403}', 9638, 2, 3, null, 'Aufnahmen sichern Beweise für die Klärung von Vorwürfen; laut Campbell-Review sinken Beschwerden, beim Gewaltgebrauch ist der Effekt unklar und am ehesten bei eng begrenztem Ermessen über das Einschalten zu erwarten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=170', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/body-worn-cameras-effects-police-officers-and-citizen-behavior', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9751, 34, 18, 'ST', 'Verbindliche Fortbildungen zur Antidiskriminierung in Verwaltung, Schule und Polizei', '{3402}', 9640, 1, 3, null, 'Schulungen erhöhen Wissen und Problembewusstsein; eine große Auswertung beim NYPD fand aber keine messbare Änderung im Kontrollverhalten. Die Wirkung auf den Umgang im Einsatz ist unsicher.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=131', 'https://www.kaxe.org/2020-09-10/nypd-study-implicit-bias-training-changes-minds-not-necessarily-behavior', 'gemischt', '2026-10-08', false, true, 'blind');

